import { promises as fs } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import type { LintDefectT } from "../../core/schema.js";
import type { LintContext, LintResult } from "../types.js";
import { compileSceneHtml, paletteFor } from "./compiler.js";
import { newPage, closePage, settlePage, waitForVideos } from "../../core/browser.js";
import { ensureDir, pathExists } from "../../core/util.js";
import { resolveAspectProfile } from "../../core/safe-zones.js";
import { resolveAssetPath, resolveSourceClipPath } from "../../core/assets.js";
import { ffprobeJson } from "../../core/ffmpeg.js";

const CRITICAL = new Set(["clip", "brokenMedia", "blankFrame", "palette", "runtime"]);
const AUDIT_FRACTIONS = [0, 0.25, 0.5, 0.75, 1];

async function customSceneSource(scene: LintContext["scene"], workspace: string): Promise<string> {
  if (scene.customHtmlFile) {
    try {
      return await fs.readFile(path.resolve(workspace, "scenes", scene.customHtmlFile), "utf8");
    } catch {
      return "";
    }
  }
  if (scene.customCode) return `${scene.customCode.html}\n<style>${scene.customCode.css}</style>\n<script>${scene.customCode.js}</script>`;
  return "";
}

/**
 * [9] A user script that reads UltraEase/__ULTRA_AUDIO BEFORE the <head>
 * injection point would capture undefined. [15] scaleX on text distorts
 * letterforms — warn and point at fontStretchPercent / font-match.
 */
function staticCustomChecks(source: string): { category: LintDefectT["category"]; detail: string; critical: boolean }[] {
  const defects: { category: LintDefectT["category"]; detail: string; critical: boolean }[] = [];
  if (!source) return defects;
  const readsPrelude = /UltraEase|__ULTRA_AUDIO/.test(source);
  if (readsPrelude) {
    const scriptMatch = /<script\b[^>]*>[\s\S]*?(?:UltraEase|__ULTRA_AUDIO)[\s\S]*?<\/script>/i.exec(source);
    if (scriptMatch) {
      const headMatch = /<head[^>]*>/i.exec(source);
      const anchor = headMatch ? headMatch.index + headMatch[0].length : (/<html[^>]*>/i.exec(source)?.index ?? 0);
      if (scriptMatch.index < anchor) {
        defects.push({
          category: "runtime",
          critical: true,
          detail:
            "custom scene reads UltraEase/__ULTRA_AUDIO in a <script> before <head>; the motion prelude is injected at the top of <head>, so this captures undefined. Move the code inside window.ultraRender(frame, fps, timeSec, progress, audio) or after <head>.",
        });
      }
    }
  }
  const ruleRe = /([^{}]+)\{([^{}]*)\}/g;
  let match: RegExpExecArray | null;
  while ((match = ruleRe.exec(source)) !== null) {
    const selector = (match[1] ?? "").trim();
    const body = match[2] ?? "";
    if (!/transform[^;]*scaleX\s*\(/i.test(body)) continue;
    const selectorNames = [...selector.matchAll(/\.([\w-]+)/g)].map((m) => m[1] ?? "");
    const textish =
      selectorNames.some((name) => /text|title|headline|heading|label|caption|subtitle|h[1-6]$/i.test(name)) ||
      selectorNames.some((name) => new RegExp(`class=["'][^"']*${name}[^"']*["'][^>]*data-audit=["']text`, "i").test(source));
    if (textish) {
      defects.push({
        category: "layout",
        critical: false,
        detail: `custom scene CSS condenses text with transform: scaleX (${selector}); this distorts letterforms — use a condensed font, fontStretchPercent, or \`ultra font-match\`.`,
      });
    }
  }
  return defects;
}

/** [17] Warn when an unanchored element visually tracks a guide (simple ±12px heuristic). */
function guideOverlapDefects(scene: LintContext["scene"]): { category: LintDefectT["category"]; detail: string; critical: boolean }[] {
  const defects: { category: LintDefectT["category"]; detail: string; critical: boolean }[] = [];
  const guides = scene.guides ?? [];
  if (guides.length === 0) return defects;
  const elements = [
    ...scene.layers.map((layer) => ({ id: layer.id, x: layer.x, y: layer.y, anchored: Boolean(layer.anchor) })),
    ...scene.textElements.map((text) => ({ id: text.id, x: text.x, y: text.y, anchored: Boolean(text.anchor) })),
  ];
  for (const element of elements) {
    if (element.anchored) continue;
    for (const guide of guides) {
      const positions = guide.keyframes.map((kf) => kf.positionPx);
      const near = guide.orientation === "v"
        ? positions.some((pos) => Math.abs(pos - element.x) <= 12)
        : positions.some((pos) => Math.abs(pos - element.y) <= 12);
      if (near) {
        defects.push({
          category: "layout",
          critical: false,
          detail: `element "${element.id}" runs along guide "${guide.id}" but is not anchored (simple ±12px overlap heuristic) — set anchor: { to: "guide:${guide.id}" } so it tracks`,
        });
      }
    }
  }
  return defects;
}

interface RawDefect {
  category: string;
  detail: string;
}

/**
 * Injected as a plain script tag (never serialized from a TS function, which
 * would drag bundler helper names like __name into the page).
 */
const AUDIT_SCRIPT = String.raw`
window.__ULTRA_AUDIT = function (params) {
  var allowedPalette = params.allowedPalette;
  var background = params.background;
  var problems = [];
  var vw = window.innerWidth;
  var vh = window.innerHeight;

  function parseColor(value) {
    if (!value || value === "transparent") return null;
    var m = value.match(/rgba?\(([^)]+)\)/);
    if (!m || !m[1]) return null;
    var parts = m[1].split(/[ ,\/]+/).filter(Boolean).map(Number);
    if (parts.length < 3 || parts.some(function (v) { return !isFinite(v); })) return null;
    return { r: parts[0], g: parts[1], b: parts[2], a: parts.length > 3 ? parts[3] : 1 };
  }
  function channelLum(v) {
    var c = v / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  }
  function luminance(c) {
    return 0.2126 * channelLum(c.r) + 0.7152 * channelLum(c.g) + 0.0722 * channelLum(c.b);
  }
  function contrast(fg, bg) {
    var l1 = luminance(fg);
    var l2 = luminance(bg);
    var hi = Math.max(l1, l2);
    var lo = Math.min(l1, l2);
    return (hi + 0.05) / (lo + 0.05);
  }
  function composite(fg, bg) {
    var a = fg.a;
    return { r: fg.r * a + bg.r * (1 - a), g: fg.g * a + bg.g * (1 - a), b: fg.b * a + bg.b * (1 - a), a: 1 };
  }
  function toHex(c) {
    function h(v) { return Math.round(v).toString(16).padStart(2, "0"); }
    return "#" + h(c.r) + h(c.g) + h(c.b);
  }
  function effectiveBg(el) {
    var cur = el.parentElement;
    while (cur) {
      var s = getComputedStyle(cur);
      var c = parseColor(s.backgroundColor);
      if (c && c.a > 0.05) return c;
      cur = cur.parentElement;
    }
    return parseColor(background) || { r: 0, g: 0, b: 0, a: 1 };
  }

  var texts = Array.prototype.slice.call(document.querySelectorAll('[data-audit="text"]'));
  var elements = Array.prototype.slice.call(document.querySelectorAll('[data-audit="el"]'));
  var all = elements.concat(texts);
  var visible = [];

  all.forEach(function (el) {
    var s = getComputedStyle(el);
    var opacity = parseFloat(s.opacity || "1");
    if (s.display === "none" || s.visibility === "hidden" || opacity < 0.02) return;
    var rect = el.getBoundingClientRect();
    if (rect.width < 0.5 && rect.height < 0.5) return;
    visible.push({ el: el, uid: el.getAttribute("data-uid") || "?", rect: rect });
    var clipExempt = el.getAttribute("data-clip-exempt") === "true";
    if (!clipExempt && (rect.left < -1 || rect.top < -1 || rect.right > vw + 1 || rect.bottom > vh + 1)) {
      problems.push({
        category: "clip",
        detail: '"' + el.getAttribute("data-uid") + '" extends outside the ' + vw + "x" + vh + " viewport (" +
          Math.round(rect.left) + "," + Math.round(rect.top) + " " + Math.round(rect.width) + "x" + Math.round(rect.height) + ")"
      });
    }
  });

  var visibleTexts = visible.filter(function (b) { return b.el.getAttribute("data-audit") === "text"; });

  for (var i = 0; i < visibleTexts.length; i += 1) {
    for (var j = i + 1; j < visibleTexts.length; j += 1) {
      var a = visibleTexts[i].rect;
      var b = visibleTexts[j].rect;
      var w = Math.min(a.right, b.right) - Math.max(a.left, b.left);
      var h = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
      if (w > 1 && h > 1) {
        var minArea = Math.min(a.width * a.height, b.width * b.height);
        if (minArea > 0 && (w * h) / minArea > 0.12) {
          problems.push({
            category: "overlap",
            detail: 'text "' + visibleTexts[i].uid + '" overlaps "' + visibleTexts[j].uid + '"'
          });
        }
      }
    }
  }

  visibleTexts.forEach(function (box) {
    var s = getComputedStyle(box.el);
    var text = (box.el.textContent || "").trim();
    if (text.length === 0) return;
    if (box.rect.width < 2 || box.rect.height < 2) {
      problems.push({ category: "layout", detail: 'text "' + box.uid + '" has no visible box' });
      return;
    }
    var fg = parseColor(s.color);
    if (fg) {
      var bg = effectiveBg(box.el);
      var ratio = contrast(composite(fg, bg), bg);
      var size = parseFloat(s.fontSize || "16");
      var weight = parseInt(s.fontWeight || "400", 10);
      var isLarge = size >= 24 || (size >= 18.66 && weight >= 700);
      var needed = isLarge ? 3.0 : 4.5;
      if (ratio < needed) {
        problems.push({
          category: "contrast",
          detail: 'text "' + box.uid + '" contrast ' + ratio.toFixed(2) + ":1 < " + needed + ":1 (" + s.color + " on " + toHex(bg) + ")"
        });
      }
      if (allowedPalette.indexOf(toHex(fg)) === -1) {
        problems.push({
          category: "palette",
          detail: 'text "' + box.uid + '" color ' + toHex(fg) + " is not in the DESIGN palette (" + allowedPalette.join(", ") + ")"
        });
      }
    }
  });

  function zoneHit(rect, zones) {
    for (var zi = 0; zi < zones.length; zi += 1) {
      var z = zones[zi];
      var iw = Math.min(rect.right, z.x + z.width) - Math.max(rect.left, z.x);
      var ih = Math.min(rect.bottom, z.y + z.height) - Math.max(rect.top, z.y);
      if (iw > 1 && ih > 1 && iw * ih > 4) return z;
    }
    return null;
  }
  visible.forEach(function (box) {
    var isCaption = box.el.getAttribute("data-caption") === "true";
    var isText = box.el.getAttribute("data-audit") === "text";
    if (!isCaption && !(params.enforceSafe && isText)) return;
    var zone = zoneHit(box.rect, params.dangerZones || []);
    if (zone) {
      problems.push({
        category: "layout",
        detail: (isCaption ? "caption" : "text") + ' "' + box.uid + '" enters the ' + zone.label + " safe-zone"
      });
    }
  });

  visible.forEach(function (box) {
    if (box.el.getAttribute("data-role") !== "shape") return;
    var s = getComputedStyle(box.el);
    var bg = parseColor(s.backgroundColor);
    if (bg && allowedPalette.indexOf(toHex(bg)) === -1) {
      problems.push({
        category: "palette",
        detail: 'shape "' + box.uid + '" color ' + toHex(bg) + " is not in the DESIGN palette"
      });
    }
  });

  Array.prototype.slice.call(document.images).forEach(function (img) {
    if (!img.complete || img.naturalWidth === 0) {
      problems.push({ category: "brokenMedia", detail: "image failed to load: " + (img.currentSrc || img.src || "?").slice(-80) });
    }
  });
  // File decodability is verified host-side with FFprobe. In the DOM only
  // genuine element errors are failures — Linux headless Chrome may leave a
  // perfectly valid file:// video at readyState 1 without ever erroring.
  Array.prototype.slice.call(document.querySelectorAll("video")).forEach(function (video) {
    if (video.error) {
      problems.push({
        category: "brokenMedia",
        detail: "video element error " + (video.error.code || "?") + ": " + (video.error.message || "decode failed"),
      });
    } else if (video.networkState === 3) {
      problems.push({ category: "brokenMedia", detail: "video has no supported source (networkState NO_SOURCE)" });
    }
  });

  let contentCount = 0;
  texts.forEach(function (el) {
    var rect = el.getBoundingClientRect();
    if ((el.textContent || "").trim().length > 0 && rect.width > 2 && rect.height > 2) contentCount += 1;
  });
  elements.forEach(function (el) {
    var tag = el.tagName.toLowerCase();
    var hasMedia = tag === "img" || tag === "video" || !!el.querySelector("img, video");
    var isShape = el.getAttribute("data-role") === "shape";
    var rect = el.getBoundingClientRect();
    if ((hasMedia || isShape) && rect.width > 4 && rect.height > 4) contentCount += 1;
  });
  if (texts.length + elements.length === 0) {
    // Custom scenes may not use audit markers at all: fall back to raw content.
    var media = document.querySelectorAll("canvas, img, video, svg");
    for (var mi = 0; mi < media.length; mi += 1) {
      var mrect = media[mi].getBoundingClientRect();
      if (mrect.width > 4 && mrect.height > 4) contentCount += 1;
    }
    if ((document.body.innerText || "").trim().length > 0) contentCount += 1;
  }
  if (contentCount === 0) {
    problems.push({ category: "blankFrame", detail: "frame contains no visible content" });
  }

  return problems;
};
`;

export async function lintScene(ctx: LintContext): Promise<LintResult> {
  const { project, scene, workspace, buildDir, fps, width, height } = ctx;
  const html = await compileSceneHtml({ project, scene, workspace, width, height, fps });
  const workDir = path.join(buildDir, "tmp");
  await ensureDir(workDir);
  const htmlPath = path.join(workDir, `lint_${scene.id.replace(/[^\w.-]/g, "_")}.html`);
  await fs.writeFile(htmlPath, html, "utf8");

  const palette = paletteFor(project, scene);
  const sceneBg = scene.background === "transparent" ? "#000000" : scene.background;

  const sceneFrames = Math.max(1, Math.round((scene.endSec - scene.startSec) * fps));
  const frameIndices = [
    ...new Set(AUDIT_FRACTIONS.map((f) => Math.min(sceneFrames - 1, Math.round(f * (sceneFrames - 1))))),
  ].sort((a, b) => a - b);

  const defects: LintDefectT[] = [];
  const seen = new Set<string>();

  // Host-side media validation: FFprobe is the deterministic source of truth
  // for whether a sourceClip / video asset actually decodes on every platform.
  const videoChecks: { id: string; file: string }[] = [];
  if (scene.sourceClip) {
    const resolved = await resolveSourceClipPath(workspace, scene.sourceClip.path).catch(() => null);
    if (resolved) videoChecks.push({ id: "sourceClip", file: resolved });
    else defects.push({ category: "brokenMedia", sceneId: scene.id, frameIndex: 0, critical: true, detail: "sourceClip file missing" });
  }
  for (const layer of scene.layers) {
    if (layer.type !== "video" || !layer.assetId) continue;
    const asset = project.assets.find((entry) => entry.id === layer.assetId);
    if (!asset) continue;
    const file = resolveAssetPath(workspace, asset);
    if (await pathExists(file)) videoChecks.push({ id: layer.id, file });
  }
  for (const check of videoChecks) {
    try {
      const probe = await ffprobeJson(check.file);
      const videoStream = probe.streams.find((stream: { codec_type?: string }) => stream.codec_type === "video");
      if (!videoStream) throw new Error("no video stream");
    } catch (err) {
      defects.push({
        category: "brokenMedia",
        sceneId: scene.id,
        frameIndex: 0,
        critical: true,
        detail: `${check.id} is not decodable: ${(err as Error).message.split("\n")[0]}`,
      });
    }
  }

  // [9] prelude ordering + [15] scaleX-text checks; [17] guide/anchor heuristic.
  if (scene.customHtmlFile || scene.customCode) {
    for (const defect of staticCustomChecks(await customSceneSource(scene, workspace))) {
      defects.push({ ...defect, sceneId: scene.id, frameIndex: 0 });
    }
  }
  for (const defect of guideOverlapDefects(scene)) {
    defects.push({ ...defect, sceneId: scene.id, frameIndex: 0 });
  }

  const page = await newPage(width, height);
  try {
    await page.goto(pathToFileURL(htmlPath).href, { waitUntil: "load" });
    await page.addScriptTag({ content: AUDIT_SCRIPT });
    await settlePage(page);
    await waitForVideos(page);
    const aspect = resolveAspectProfile(project.meta);
    const dangerZones = aspect.zones.dangerZones.map((zone) => ({
      id: zone.id,
      label: `${aspect.aspect} ${zone.label}`,
      x: zone.rect.x * width,
      y: zone.rect.y * height,
      width: zone.rect.width * width,
      height: zone.rect.height * height,
    }));
    const auditArgs = JSON.stringify({
      allowedPalette: palette,
      background: sceneBg,
      dangerZones,
      enforceSafe: aspect.explicit,
    });
    for (const frameIndex of frameIndices) {
      await page.evaluate(`window.__ULTRA_SEEK(${frameIndex}, ${fps})`);
      // Guarantee the seeked video has a decoded frame before auditing media.
      await waitForVideos(page);
      const raw = (await page.evaluate(`window.__ULTRA_AUDIT(${auditArgs})`)) as RawDefect[];
      for (const problem of raw) {
        const key = `${problem.category}::${problem.detail}`;
        if (seen.has(key)) continue;
        seen.add(key);
        defects.push({
          category: problem.category as LintDefectT["category"],
          sceneId: scene.id,
          frameIndex,
          critical: CRITICAL.has(problem.category),
          detail: problem.detail,
        });
      }
    }
  } finally {
    await closePage(page);
  }

  const criticalCount = defects.filter((d) => d.critical).length;
  return { defects, pass: criticalCount === 0 };
}
